prompt:
You are building a personal progress tracking system. Complete the following steps and save all results to the specified files.

Step 1: Create a quantified self data file at quantified_self.json with this exact structure:
{
  "initialized_at": "2024-01-15T09:00:00Z",
  "last_update": "2024-01-15T17:30:00Z",
  "growth": {
    "baseline": {"overall": 42.0, "knowledge": 8.0, "capability": 55.0, "quality": 62.0, "efficiency": 38.0},
    "current": {"overall": 48.5, "knowledge": 22.0, "capability": 63.0, "quality": 70.0, "efficiency": 44.0},
    "history": [
      {"timestamp": "2024-01-15T12:00:00Z", "overall": 44.0},
      {"timestamp": "2024-01-15T17:30:00Z", "overall": 48.5}
    ]
  },
  "tasks": {
    "total": 15,
    "completed": 12,
    "in_progress": 2,
    "failed": 1,
    "completion_rate": 80.0,
    "average_quality": 8.1,
    "by_type": {"coding": 6, "debugging": 4, "design": 3, "documentation": 2}
  },
  "learning": {
    "new_concepts": [
      {"name": "async/await patterns", "mastery": 80, "applied_count": 4, "source": "task_execution"},
      {"name": "SQL window functions", "mastery": 65, "applied_count": 2, "source": "user_question"}
    ],
    "total_concepts": 2,
    "by_category": {"programming": 1, "databases": 1}
  },
  "efficiency": {
    "avg_response_time": 1.9,
    "first_try_success_rate": 80.0,
    "avg_iterations": 1.5,
    "time_distribution": {"thinking": 30, "tools": 50, "output": 20}
  },
  "achievements": [
    {"type": "milestone", "title": "Completed first multi-step debugging session", "timestamp": "2024-01-15T14:00:00Z", "icon": "milestone"}
  ],
  "goals": [
    {"name": "Master async programming", "progress": 80, "target": 100, "unit": "%", "eta_days": 2}
  ],
  "daily_stats": {
    "2024-01-15": {
      "conversations": 18,
      "tasks_completed": 12,
      "concepts_learned": 2,
      "achievements": 1,
      "overall_growth": 6.5
    }
  }
}

Step 2: Using the data in quantified_self.json, compute a growth summary and save it to growth_summary.json with these exact fields:
- overall_growth_delta: current.overall minus baseline.overall (rounded to 1 decimal)
- completion_rate: the tasks.completion_rate value
- top_category: the task category with the highest count (string key from by_type)
- total_concepts_learned: learning.total_concepts
- first_try_rate: efficiency.first_try_success_rate

Save growth_summary.json as a flat JSON object with exactly those 5 fields.
